/** HTTP contract details both api and web must agree on. */
export const API = {
  /** Correlation id header; generated by the API when the client does not send one. */
  REQUEST_ID_HEADER: 'x-request-id',
  /** Cookie carrying the refresh token (httpOnly). */
  REFRESH_COOKIE: 'ircub_refresh',
  /** Path prefix the nginx image proxies to the API container. */
  PROXY_PREFIX: '/api',
} as const;

export const HEALTH_STATUS = {
  OK: 'ok',
  DEGRADED: 'degraded',
  DOWN: 'down',
} as const;

export type HealthStatus = (typeof HEALTH_STATUS)[keyof typeof HEALTH_STATUS];

export const CHECK_STATUS = {
  UP: 'up',
  DOWN: 'down',
} as const;

export type CheckStatus = (typeof CHECK_STATUS)[keyof typeof CHECK_STATUS];
